import pandas as pd
import numpy as np
from collections import defaultdict

# Load data
df = pd.read_csv('chunks_csv/cyclehire_w004.csv')
adj_df = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Compute Self-Containment Ratios
grouped = df.groupby('StartBorough')
def compute_ratio(group):
    return ((group['EndBorough'] == group.name).sum() / len(group))

ratios_series = grouped.apply(compute_ratio)
ratios_series.name = 'Self_Containment_Ratio'

# Build adjacency list
borough_neighbors = defaultdict(list)
for _, row in adj_df.iterrows():
    borough = row['borough']
    neighbor = row['neighbor']
    borough_neighbors[borough].append(neighbor)

# Compute average neighbor ratios
average_neighbor_ratios = {}
for borough in ratios_series.index:
    neighbors = borough_neighbors.get(borough, [])
    if not neighbors:
        avg = np.nan
    else:
        neighbor_ratios = [ratios_series[neighbor] for neighbor in neighbors if neighbor in ratios_series]
        if not neighbor_ratios:
            avg = np.nan
        else:
            avg = np.mean(neighbor_ratios)
    average_neighbor_ratios[borough] = avg

# Compute mean and std of ratios
mean_ratio = ratios_series.mean()
std_ratio = ratios_series.std()

# Identify candidates
candidates = []
for borough in ratios_series.index:
    ratio = ratios_series[borough]
    avg_neighbor = average_neighbor_ratios[borough]
    if np.isnan(avg_neighbor):
        continue
    if ratio > mean_ratio + std_ratio and avg_neighbor > mean_ratio + std_ratio:
        candidates.append((borough, 'HH'))
    elif ratio < mean_ratio - std_ratio and avg_neighbor < mean_ratio - std_ratio:
        candidates.append((borough, 'LL'))

# Perform permutation tests
results = []
for borough, candidate_type in candidates:
    observed_avg = average_neighbor_ratios[borough]
    original_ratios = ratios_series.values
    boroughs_list = ratios_series.index.tolist()
    count = 0
    for _ in range(500):
        shuffled = np.random.permutation(original_ratios)
        shuffled_dict = dict(zip(boroughs_list, shuffled))
        neighbors = borough_neighbors.get(borough, [])
        if not neighbors:
            continue
        neighbor_ratios = [shuffled_dict.get(neighbor, np.nan) for neighbor in neighbors]
        valid_ratios = [r for r in neighbor_ratios if not np.isnan(r)]
        if not valid_ratios:
            continue
        shuffled_avg = np.mean(valid_ratios)
        if candidate_type == 'HH':
            if shuffled_avg >= observed_avg:
                count += 1
        elif candidate_type == 'LL':
            if shuffled_avg <= observed_avg:
                count += 1
    p_value = count / 500
    if p_value < 0.05:
        results.append((borough, candidate_type, p_value))

# Prepare final output
final_output = []
for borough, typ, _ in results:
    final_output.append(f"{borough} ({typ}, statistical method=permutation)")

print(f"data_points_used = {len(df)}")
if final_output:
    print("FINAL ANSWER: " + ", ".join(final_output))
else:
    print("FINAL ANSWER: none")
